import { MakeLogicType, actions, connect, kea, listeners, path, reducers } from 'kea'
import { router } from 'kea-router'
import type { LocationChangedPayload } from 'kea-router/lib/types'
import posthog from 'posthog-js'

import { removeProjectIdIfPresent } from 'lib/utils/kea-router'
import { urls } from 'scenes/urls'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayHomeEditLogicValues {
    homeEditing: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayHomeEditLogicActions {
    locationChanged: ({
        method,
        pathname,
        search,
        searchParams,
        hash,
        hashParams,
        initial,
        url,
        routerState,
    }: LocationChangedPayload) => {
        hash: string
        hashParams: Record<string, any>
        initial: boolean
        method: 'POP' | 'PUSH' | 'REPLACE'
        pathname: string
        routerState: Record<string, any>
        search: string
        searchParams: Record<string, any>
        url: string
    } // router
    toggleHomeEditing: () => {
        value: true
    }
}

export type todayHomeEditLogicType = MakeLogicType<todayHomeEditLogicValues, todayHomeEditLogicActions>

export const todayHomeEditLogic = kea<todayHomeEditLogicType>([
    path(['scenes', 'project-homepage', 'today', 'todayHomeEditLogic']),
    connect(() => ({
        actions: [router, ['locationChanged']],
    })),
    actions({
        toggleHomeEditing: true,
    }),
    reducers({
        // Edits save as they happen, so leaving edit mode has nothing to commit.
        homeEditing: [
            false,
            {
                toggleHomeEditing: (editing) => !editing,
                // Ends on navigation rather than on unmount: a render React discards can leave a kea mount behind.
                locationChanged: (editing, { pathname }) =>
                    editing && removeProjectIdIfPresent(pathname) === urls.projectHomepage(),
            },
        ],
    }),
    listeners(({ values }) => ({
        toggleHomeEditing: () => {
            posthog.capture(values.homeEditing ? 'today home edit started' : 'today home edit saved')
        },
    })),
])
